const createStepHistory = () => {
  const history = new Map([])
  let cursor = 0
  let pending = null

  const startRun = () => {
    cursor = 0
  }

  const nextStep = () => {
    const index = cursor
    cursor++
    return {index, saved: history.get(index)}
  }

  const recordSuccess = (index, event) => {
    history.set(index, event)
  }

  const recordFailure = (index, {event, error, delayMs}) => {
    const retryable = event.attempt <= event.retries && error?.name !== 'UnrecoverableError'

    if (retryable) {
      history.set(index, {...event, output: error, retryDelayMs: delayMs})
      pending = {index, event, delayMs}
    } else {
      history.set(index, {...event, output: error})
    }
    return retryable
  }

  const getPending = () => {
    const item = pending
    pending = null
    return item
  }

  const settle = ({index, event}) => {
    history.set(index, {...event, output: history.get(index).output})
  }

  return {
    startRun,
    nextStep,
    recordSuccess,
    recordFailure,
    getPending,
    settle,
  }
}

export {createStepHistory}
